import random
from itertools import combinations

def has_triangle(edges, n):
    """Check if graph has a triangle (3-cycle)"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        return True
    return False

def has_4cycle(edges, n):
    """Check if graph has a 4-cycle"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check for 4-cycles: a-b-c-d-a
    for a in range(n):
        for b in adj[a]:
            if b > a:
                for c in adj[b]:
                    if c > b and c != a:
                        for d in adj[c]:
                            if d > c and d in adj[a] and d != b:
                                return True
    return False

def girth_at_least_5(edges, n):
    """Check if girth is at least 5"""
    return not has_triangle(edges, n) and not has_4cycle(edges, n)

def chromatic_number(edges, n, max_colors=5):
    """Check if graph is colorable with at most max_colors"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Backtracking coloring
    colors = [-1] * n

    def is_safe(v, c):
        for neighbor in adj[v]:
            if colors[neighbor] == c:
                return False
        return True

    def color_graph(v):
        if v == n:
            return True
        for c in range(max_colors):
            if is_safe(v, c):
                colors[v] = c
                if color_graph(v + 1):
                    return True
                colors[v] = -1
        return False

    return color_graph(0)

def try_random_graph(n, num_edges, max_attempts=10000):
    """Try to find a random graph with the required properties"""
    for _ in range(max_attempts):
        edges = set()
        while len(edges) < num_edges:
            u, v = random.sample(range(n), 2)
            if u > v:
                u, v = v, u
            edges.add((u, v))
        edges = list(edges)

        if girth_at_least_5(edges, n):
            if chromatic_number(edges, n, 5):
                return edges
    return None

