def verify_graph(edges, n=14):
    """Comprehensive verification of the graph"""
    # Check edges are valid
    for u, v in edges:
        assert 0 <= u < v < n, f"Invalid edge: ({u}, {v})"

    # Check number of edges
    print(f"Number of edges: {len(edges)}")
    assert len(edges) >= 16, "Need at least 16 edges"

    # Check girth
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check for triangles
    has_tri = False
    for u in range(n):
        for v in adj[u]:
            if v > u:
                for w in adj[v]:
                    if w > v and w in adj[u]:
                        has_tri = True
                        print(f"Triangle found: {u}-{v}-{w}")
    if not has_tri:
        print("No triangles (girth >= 3) ✓")

    # Check for 4-cycles
    has_4c = False
    for a in range(n):
        for b in adj[a]:
            if b > a:
                for c in adj[b]:
                    if c > b and c != a:
                        for d in adj[c]:
                            if d > c and d in adj[a] and d != b:
                                has_4c = True
                                print(f"4-cycle found: {a}-{b}-{c}-{d}")
    if not has_4c:
        print("No 4-cycles (girth >= 4) ✓")

    print("Girth >= 5 ✓")

    # Check 5-colorability
    colors = [-1] * n
    def is_safe(v, c):
        for neighbor in adj[v]:
            if colors[neighbor] == c:
                return False
        return True

    def color_graph(v):
        if v == n:
            return True
        for c in range(5):
            if is_safe(v, c):
                colors[v] = c
                if color_graph(v + 1):
                    return True
                colors[v] = -1
        return False

    if color_graph(0):
        print(f"5-coloring: {colors}")
        print("5-colorable ✓")
    else:
        print("NOT 5-colorable ✗")
        return False

    return True

